draft.Filters.Add("leather");
Console.WriteLine($"{again.Filters.Count} vs {draft.Filters.Count}"); // 3 vs 3

public record SearchQuery(string Term, List<string> Filters);

using System.Collections.Immutable;

var cache = new Dictionary<SearchQuery, int>();
cache[new SearchQuery("shoes", ["red", "sale"])] = 42;

var again = new SearchQuery("shoes", ["red", "sale"]);
Console.WriteLine(cache.ContainsKey(again)); // True: compares the items

var draft = again with { Term = "boots", Filters = again.Filters.Add("leather") };
Console.WriteLine($"{again.Filters.Length} vs {draft.Filters.Length}"); // 2 vs 3

public sealed record SearchQuery(string Term, ImmutableArray<string> Filters)
{
    public bool Equals(SearchQuery? other) => other is not null
        && Term == other.Term && Filters.SequenceEqual(other.Filters);

    public override int GetHashCode()
    {
        var hash = new HashCode();
        hash.Add(Term);
        foreach (var filter in Filters) hash.Add(filter);
        return hash.ToHashCode();
    }
}
